            }
            return addToMetadata(FEATURE_IMPORTANCE_BASELINE, featureImportanceBaseline.asMap());
        }

        public Builder setHyperparameters(List<Hyperparameters> hyperparameters) {
            if (hyperparameters == null) {
                return this;
            }
            return addToMetadata(HYPERPARAMETERS, hyperparameters.stream().map(Hyperparameters::asMap).collect(Collectors.toList()));
        }

        public Builder setPlatformArchitecture(String platformArchitecture) {
            this.platformArchitecture = platformArchitecture;
            return this;
        }

        public Builder setPrefixStrings(TrainedModelPrefixStrings prefixStrings) {
            this.prefixStrings = prefixStrings;
            return this;
        }

        public Builder setModelAliases(Set<String> modelAliases) {
            if (modelAliases == null || modelAliases.isEmpty()) {
                return this;
            }
            return addToMetadata(MODEL_ALIASES, modelAliases.stream().sorted().collect(Collectors.toList()));
        }

        private Builder addToMetadata(String fieldName, Object value) {
            if (this.metadata == null) {
                this.metadata = new HashMap<>();
            }
            this.metadata.put(fieldName, value);
            return this;
        }

        public Builder setParsedDefinition(TrainedModelDefinition.Builder definitionRef) {
            if (definitionRef == null) {
                return this;
            }
            this.definition = LazyModelDefinition.fromParsedDefinition(definitionRef.build());
            return this;
        }

        public Builder setDefinitionFromBytes(BytesReference definitionRef) {
            if (definitionRef == null) {
                return this;
            }
            this.definition = LazyModelDefinition.fromCompressedData(definitionRef);
            return this;
        }

        public Builder clearDefinition() {
            this.definition = null;
            return this;
        }

        private Builder setLazyDefinition(TrainedModelDefinition.Builder parsedTrainedModel) {
            if (parsedTrainedModel == null) {
                return this;
            }

            if (this.definition != null) {
                throw new IllegalArgumentException(
                    format("both [%s] and [%s] cannot be set.", COMPRESSED_DEFINITION.getPreferredName(), DEFINITION.getPreferredName())
                );
            }
            this.definition = LazyModelDefinition.fromParsedDefinition(parsedTrainedModel.build());
            return this;
        }

        private Builder setLazyDefinition(String compressedString) {
            if (compressedString == null) {
                return this;
            }

            if (this.definition != null) {
                throw new IllegalArgumentException(
                    format("both [%s] and [%s] cannot be set.", COMPRESSED_DEFINITION.getPreferredName(), DEFINITION.getPreferredName())
                );
            }
            this.definition = LazyModelDefinition.fromBase64String(compressedString);
            return this;
        }

        public Builder setLocation(TrainedModelLocation location) {
            this.location = location;
            return this;
        }

        public Builder setInput(TrainedModelInput input) {
            this.input = input;
            return this;
        }

        public Builder setModelSize(long modelSize) {
            this.modelSize = modelSize;
            return this;
        }

        public Builder setEstimatedOperations(long estimatedOperations) {
            this.estimatedOperations = estimatedOperations;
            return this;
        }

        public Builder setLicenseLevel(String licenseLevel) {
            this.licenseLevel = licenseLevel;
            return this;
        }

        public Builder setDefaultFieldMap(Map<String, String> defaultFieldMap) {
            this.defaultFieldMap = defaultFieldMap;
            return this;
        }

        public Builder setInferenceConfig(InferenceConfig inferenceConfig) {
            this.inferenceConfig = inferenceConfig;
            return this;
        }

        public Builder validate() {
            return validate(false);
        }

        /**
         * Runs validations against the builder.
         * @param forCreation indicates if we should validate for model creation or for a model read from storage
         * @return The current builder object if validations are successful
         * @throws ActionRequestValidationException when there are validation failures.
         */
        public Builder validate(boolean forCreation) {
            // We require a definition to be available here even though it will be stored in a different doc
            ActionRequestValidationException validationException = null;
            boolean packagedModel = modelId != null && modelId.startsWith(".");

            if (modelId == null) {
                validationException = addValidationError("[" + MODEL_ID.getPreferredName() + "] must not be null.", validationException);
            }

            if (packagedModel == false) {
                if (definition != null && location != null) {
                    validationException = addValidationError(
                        "["
                            + DEFINITION.getPreferredName()
                            + "] "
                            + "and ["
                            + LOCATION.getPreferredName()
                            + "] are both defined but only one can be used.",
                        validationException
                    );
                }
                if (definition == null && modelType == null) {
                    validationException = addValidationError(
                        "["
                            + MODEL_TYPE.getPreferredName()
                            + "] must be set if "
                            + "["
                            + DEFINITION.getPreferredName()
                            + "] is not defined.",
                        validationException
                    );
                }

                if (inferenceConfig == null && forCreation) {
                    validationException = addValidationError(
                        "[" + INFERENCE_CONFIG.getPreferredName() + "] must not be null.",
                        validationException
                    );
                }
            }

            if (modelId != null) {
                if (packagedModel) {
                    String idToValidate = modelId.substring(1);
                    if (idToValidate.endsWith("_SNAPSHOT")) {
                        idToValidate = idToValidate.substring(0, idToValidate.length() - 9);
                    }

                    if (MlStrings.isValidId(idToValidate) == false) {
                        validationException = addValidationError(
                            Messages.getMessage(Messages.INVALID_MODEL_PACKAGE_ID, TrainedModelConfig.MODEL_ID.getPreferredName(), modelId),
                            validationException
                        );
                    }
                } else {
                    if (MlStrings.isValidId(modelId) == false) {
                        validationException = addValidationError(
                            Messages.getMessage(Messages.INVALID_ID, TrainedModelConfig.MODEL_ID.getPreferredName(), modelId),
                            validationException
                        );
                    }
                }
            }

            if (modelId != null && MlStrings.hasValidLengthForId(modelId) == false) {
                validationException = addValidationError(
                    Messages.getMessage(
                        Messages.ID_TOO_LONG,
                        TrainedModelConfig.MODEL_ID.getPreferredName(),
                        modelId,
                        MlStrings.ID_LENGTH_LIMIT
                    ),
                    validationException
                );
            }
            List<String> badTags = tags.stream()
                .filter(tag -> (MlStrings.isValidId(tag) && MlStrings.hasValidLengthForId(tag)) == false)
                .collect(Collectors.toList());
            if (badTags.isEmpty() == false) {
                validationException = addValidationError(
                    Messages.getMessage(Messages.INFERENCE_INVALID_TAGS, badTags, MlStrings.ID_LENGTH_LIMIT),
                    validationException
                );
            }

            for (String tag : tags) {
                if (tag.equals(modelId)) {
                    validationException = addValidationError("none of the tags must equal the model_id", validationException);
                    break;
                }
            }
            if (input != null && input.getFieldNames().isEmpty()) {
                validationException = addValidationError("[input.field_names] must not be empty", validationException);
            }
            validationException = validateTrainedModelInput(validationException, input);
            if (forCreation) {
                validationException = checkIllegalSetting(version, VERSION.getPreferredName(), validationException);
                validationException = checkIllegalSetting(createdBy, CREATED_BY.getPreferredName(), validationException);
                validationException = checkIllegalSetting(createTime, CREATE_TIME.getPreferredName(), validationException);
                validationException = checkIllegalSetting(licenseLevel, LICENSE_LEVEL.getPreferredName(), validationException);
                validationException = checkIllegalSetting(location, LOCATION.getPreferredName(), validationException);
                if (metadata != null) {
                    validationException = checkIllegalSetting(
                        metadata.get(TOTAL_FEATURE_IMPORTANCE),
                        METADATA.getPreferredName() + "." + TOTAL_FEATURE_IMPORTANCE,
                        validationException
                    );
                    validationException = checkIllegalSetting(
                        metadata.get(MODEL_ALIASES),
                        METADATA.getPreferredName() + "." + MODEL_ALIASES,
                        validationException
                    );
                }

                // packaged model validation
                validationException = checkIllegalSetting(modelPackageConfig, MODEL_PACKAGE.getPreferredName(), validationException);
            }
            if (validationException != null) {
                throw validationException;
            }

            return this;
        }

        private ActionRequestValidationException validateTrainedModelInput(ActionRequestValidationException validationException, TrainedModelInput input) {
            if (input != null
                && input.getFieldNames()
                    .stream()
                    .filter(s -> s.contains("."))
                    .flatMap(s -> Arrays.stream(Strings.delimitedListToStringArray(s, ".")))
                    .anyMatch(String::isEmpty)) {
                validationException = addValidationError(
                    "[input.field_names] must only contain valid dot delimited field names",
                    validationException
                );
            }
            return validationException;
        }

        /**
         * Validate that fields defined by the package aren't defined in the request.
         *
         * To be called by the transport after checking that the package exists.
         */
        public Builder validateNoPackageOverrides() {
            ActionRequestValidationException validationException = null;
            validationException = checkIllegalPackagedModelSetting(description, DESCRIPTION.getPreferredName(), validationException);
            validationException = checkIllegalPackagedModelSetting(definition, DEFINITION.getPreferredName(), validationException);
            validationException = checkIllegalPackagedModelSetting(modelType, MODEL_TYPE.getPreferredName(), validationException);
            validationException = checkIllegalPackagedModelSetting(metadata, METADATA.getPreferredName(), validationException);
            if (modelSize != null && modelSize > 0) {
                validationException = checkIllegalPackagedModelSetting(modelSize, MODEL_SIZE_BYTES.getPreferredName(), validationException);
            }
            validationException = checkIllegalPackagedModelSetting(
                inferenceConfig,
                INFERENCE_CONFIG.getPreferredName(),
                validationException
            );
            if (tags != null && tags.isEmpty() == false) {
                validationException = addValidationError(
                    "illegal to set [tags] at inference model creation for packaged model",
                    validationException
                );
            }

            if (validationException != null) {
                throw validationException;
            }

            return this;
        }

        private static ActionRequestValidationException checkIllegalSetting(
            Object value,
            String setting,
            ActionRequestValidationException validationException
        ) {
            if (value != null) {
                return addValidationError("illegal to set [" + setting + "] at inference model creation", validationException);
            }
            return validationException;
        }

        private static ActionRequestValidationException checkIllegalPackagedModelSetting(
            Object value,
            String setting,
            ActionRequestValidationException validationException
        ) {
            if (value != null) {
                return addValidationError(
                    "illegal to set [" + setting + "] at inference model creation for packaged model",
                    validationException
                );
            }
            return validationException;
        }

        public TrainedModelConfig build() {
            return new TrainedModelConfig(
                modelId,
                modelType,
                createdBy == null ? "user" : createdBy,
                version == null ? MlConfigVersion.CURRENT : version,
                description,
                createTime == null ? Instant.now() : createTime,
                definition,
                tags,
                metadata,
                input,
                modelSize == null ? 0 : modelSize,
                estimatedOperations == null ? 0 : estimatedOperations,
                licenseLevel == null ? License.OperationMode.PLATINUM.description() : licenseLevel,
                defaultFieldMap,
                inferenceConfig,
                location,
                modelPackageConfig,
                platformArchitecture,
                prefixStrings
            );
        }
    }

/**
 * A request to execute search against one or more indices (or all).
 * <p>
 * Note, the search {@link #source(org.elasticsearch.search.builder.SearchSourceBuilder)}
 * is required. The search source is the different search options, including aggregations and such.
 * </p>
 *
 * @see org.elasticsearch.client.internal.Client#search(SearchRequest)
 * @see SearchResponse
 */
public class SearchRequest extends ActionRequest implements IndicesRequest.Replaceable, Rewriteable<SearchRequest> {

    public static final ToXContent.Params FORMAT_PARAMS = new ToXContent.MapParams(Collections.singletonMap("pretty", "false"));

    public static final int DEFAULT_PRE_FILTER_SHARD_SIZE = 128;
    public static final int DEFAULT_BATCHED_REDUCE_SIZE = 512;

    private static final long DEFAULT_ABSOLUTE_START_MILLIS = -1;

    private final String localClusterAlias;
    private final long absoluteStartMillis;
    private final boolean finalReduce;

    private SearchType searchType = SearchType.DEFAULT;

    private String[] indices = Strings.EMPTY_ARRAY;

    @Nullable
    private String routing;
    @Nullable
    private String preference;

    private SearchSourceBuilder source;

    private Boolean requestCache;

    private Boolean allowPartialSearchResults;

    private Scroll scroll;

    private int batchedReduceSize = DEFAULT_BATCHED_REDUCE_SIZE;

    private int maxConcurrentShardRequests = 0;
    public static final int DEFAULT_MAX_CONCURRENT_SHARD_REQUESTS = 5;

    private Integer preFilterShardSize;

    private boolean ccsMinimizeRoundtrips;

    @Nullable
    private final Version minCompatibleShardNode;

    public static final IndicesOptions DEFAULT_INDICES_OPTIONS = IndicesOptions.strictExpandOpenAndForbidClosedIgnoreThrottled();

    private IndicesOptions indicesOptions = DEFAULT_INDICES_OPTIONS;

    private Map<String, long[]> waitForCheckpoints = Collections.emptyMap();

    private TimeValue waitForCheckpointsTimeout = TimeValue.timeValueSeconds(30);

    /**
     * Should this request force {@link SourceLoader.Synthetic synthetic source}?
     * Use this to test if the mapping supports synthetic _source and to get a sense
     * of the worst case performance. Fetches with this enabled will be slower the
     * enabling synthetic source natively in the index.
     */
    private boolean forceSyntheticSource = false;

    public SearchRequest() {
        this((Version) null);
    }

    public SearchRequest(Version minCompatibleShardNode) {
        this.localClusterAlias = null;
        this.absoluteStartMillis = DEFAULT_ABSOLUTE_START_MILLIS;
        this.finalReduce = true;
        this.minCompatibleShardNode = minCompatibleShardNode;
        this.ccsMinimizeRoundtrips = minCompatibleShardNode == null;
    }

    /**
     * Constructs a new search request from the provided search request
     */
    public SearchRequest(SearchRequest searchRequest) {
        this(
            searchRequest,
            searchRequest.indices,
            searchRequest.localClusterAlias,
            searchRequest.absoluteStartMillis,
            searchRequest.finalReduce
        );
    }

    /**
     * Constructs a new search request against the indices. No indices provided here means that search
     * will run against all indices.
     */
    public SearchRequest(String... indices) {
        this(indices, new SearchSourceBuilder());
    }

    /**
     * Constructs a new search request against the provided indices with the given search source.
     */
    @SuppressWarnings("this-escape")
    public SearchRequest(String[] indices, SearchSourceBuilder source) {
        this();
        if (source == null) {
            throw new IllegalArgumentException("source must not be null");
        }
        indices(indices);
        this.source = source;
    }

    @Override
    public boolean allowsRemoteIndices() {
        return true;
    }

    /**
     * Creates a new sub-search request starting from the original search request that is provided.
     * For internal use only, allows to fork a search request into multiple search requests that will be executed independently.
     * Such requests will not be finally reduced, so that their results can be merged together in one response at completion.
     * Used when a {@link SearchRequest} is created and executed as part of a cross-cluster search request
     * performing reduction on each cluster in order to minimize network round-trips between the coordinating node and the remote clusters.
     *
     * @param parentTaskId the parent taskId of the original search request
     * @param originalSearchRequest the original search request
     * @param indices the indices to search against
     * @param clusterAlias the alias to prefix index names with in the returned search results
     * @param absoluteStartMillis the absolute start time to be used on the remote clusters to ensure that the same value is used
     * @param finalReduce whether the reduction should be final or not
     */
    static SearchRequest subSearchRequest(
        TaskId parentTaskId,
        SearchRequest originalSearchRequest,
        String[] indices,
        String clusterAlias,
        long absoluteStartMillis,
        boolean finalReduce
    ) {
        Objects.requireNonNull(parentTaskId, "parentTaskId must be specified");
        Objects.requireNonNull(originalSearchRequest, "search request must not be null");
        validateIndices(indices);
        Objects.requireNonNull(clusterAlias, "cluster alias must not be null");
        if (absoluteStartMillis < 0) {
            throw new IllegalArgumentException("absoluteStartMillis must not be negative but was [" + absoluteStartMillis + "]");
        }
        final SearchRequest request = new SearchRequest(originalSearchRequest, indices, clusterAlias, absoluteStartMillis, finalReduce);
        request.setParentTask(parentTaskId);
        return request;
    }

    private SearchRequest(
        SearchRequest searchRequest,
        String[] indices,
        String localClusterAlias,
        long absoluteStartMillis,
        boolean finalReduce
    ) {
        this.allowPartialSearchResults = searchRequest.allowPartialSearchResults;
        this.batchedReduceSize = searchRequest.batchedReduceSize;
        this.ccsMinimizeRoundtrips = searchRequest.ccsMinimizeRoundtrips;
        this.indices = indices;
        this.indicesOptions = searchRequest.indicesOptions;
        this.maxConcurrentShardRequests = searchRequest.maxConcurrentShardRequests;
        this.preference = searchRequest.preference;
        this.preFilterShardSize = searchRequest.preFilterShardSize;
        this.requestCache = searchRequest.requestCache;
        this.routing = searchRequest.routing;
        this.scroll = searchRequest.scroll;
        this.searchType = searchRequest.searchType;
        this.source = searchRequest.source;
        this.localClusterAlias = localClusterAlias;
        this.absoluteStartMillis = absoluteStartMillis;
        this.finalReduce = finalReduce;
        this.minCompatibleShardNode = searchRequest.minCompatibleShardNode;
        this.waitForCheckpoints = searchRequest.waitForCheckpoints;
        this.waitForCheckpointsTimeout = searchRequest.waitForCheckpointsTimeout;
        this.forceSyntheticSource = searchRequest.forceSyntheticSource;
    }

    /**
     * Constructs a new search request from reading the specified stream.
     *
     * @param in The stream the request is read from
     * @throws IOException if there is an issue reading the stream
     */
    public SearchRequest(StreamInput in) throws IOException {
        super(in);
        searchType = SearchType.fromId(in.readByte());
        indices = in.readStringArray();
        routing = in.readOptionalString();
        preference = in.readOptionalString();
        scroll = in.readOptionalWriteable(Scroll::new);
        source = in.readOptionalWriteable(SearchSourceBuilder::new);
        if (in.getTransportVersion().before(TransportVersions.V_8_0_0)) {
            // types no longer relevant so ignore
            String[] types = in.readStringArray();
            if (types.length > 0) {
                throw new IllegalStateException(
                    "types are no longer supported in search requests but found [" + Arrays.toString(types) + "]"
                );
            }
        }
        indicesOptions = IndicesOptions.readIndicesOptions(in);
        requestCache = in.readOptionalBoolean();
        batchedReduceSize = in.readVInt();
        maxConcurrentShardRequests = in.readVInt();
        preFilterShardSize = in.readOptionalVInt();
        allowPartialSearchResults = in.readOptionalBoolean();
        localClusterAlias = in.readOptionalString();
        if (localClusterAlias != null) {
            absoluteStartMillis = in.readVLong();
            finalReduce = in.readBoolean();
        } else {
            absoluteStartMillis = DEFAULT_ABSOLUTE_START_MILLIS;
            finalReduce = true;
        }
        ccsMinimizeRoundtrips = in.readBoolean();
        if (in.readBoolean()) {
            minCompatibleShardNode = Version.readVersion(in);
        } else {
            minCompatibleShardNode = null;
        }
        waitForCheckpoints = in.readMap(StreamInput::readLongArray);
        waitForCheckpointsTimeout = in.readTimeValue();
        if (in.getTransportVersion().onOrAfter(TransportVersions.V_8_4_0)) {
            forceSyntheticSource = in.readBoolean();
        } else {
            forceSyntheticSource = false;
        }
    }

    @Override
    public void writeTo(StreamOutput out) throws IOException {
        super.writeTo(out);
        out.writeByte(searchType.id());
        out.writeStringArray(indices);
        out.writeOptionalString(routing);
        out.writeOptionalString(preference);
        out.writeOptionalWriteable(scroll);
        out.writeOptionalWriteable(source);
        if (out.getTransportVersion().before(TransportVersions.V_8_0_0)) {
            // types not supported so send an empty array to previous versions
            out.writeStringArray(Strings.EMPTY_ARRAY);
        }
        indicesOptions.writeIndicesOptions(out);
        out.writeOptionalBoolean(requestCache);
        out.writeVInt(batchedReduceSize);
        out.writeVInt(maxConcurrentShardRequests);
        out.writeOptionalVInt(preFilterShardSize);
        out.writeOptionalBoolean(allowPartialSearchResults);
        out.writeOptionalString(localClusterAlias);
        if (localClusterAlias != null) {
            out.writeVLong(absoluteStartMillis);
            out.writeBoolean(finalReduce);
        }
        out.writeBoolean(ccsMinimizeRoundtrips);
        out.writeBoolean(minCompatibleShardNode != null);
        if (minCompatibleShardNode != null) {
            Version.writeVersion(minCompatibleShardNode, out);
        }
        out.writeMap(waitForCheckpoints, StreamOutput::writeLongArray);
        out.writeTimeValue(waitForCheckpointsTimeout);
        if (out.getTransportVersion().onOrAfter(TransportVersions.V_8_4_0)) {
            out.writeBoolean(forceSyntheticSource);
        } else {
            if (forceSyntheticSource) {
                throw new IllegalArgumentException("force_synthetic_source is not supported before 8.4.0");
            }
        }
    }

    @Override
    public ActionRequestValidationException validate() {
        ActionRequestValidationException validationException = null;
        boolean scroll = scroll() != null;
        if (scroll) {
            if (source != null) {
                if (source.trackTotalHitsUpTo() != null && source.trackTotalHitsUpTo() != SearchContext.TRACK_TOTAL_HITS_ACCURATE) {
                    validationException = addValidationError(
                        "disabling [track_total_hits] is not allowed in a scroll context",
                        validationException
                    );
                }
                if (source.from() > 0) {
                    validationException = addValidationError("using [from] is not allowed in a scroll context", validationException);
                }
                if (source.size() == 0) {
                    validationException = addValidationError("[size] cannot be [0] in a scroll context", validationException);
                }
                if (source.rescores() != null && source.rescores().isEmpty() == false) {
                    validationException = addValidationError("using [rescore] is not allowed in a scroll context", validationException);
                }
                if (CollectionUtils.isEmpty(source.searchAfter()) == false) {
                    validationException = addValidationError("[search_after] cannot be used in a scroll context", validationException);
                }
                if (source.collapse() != null) {
                    validationException = addValidationError("cannot use `collapse` in a scroll context", validationException);
                }
            }
            if (requestCache != null && requestCache) {
                validationException = addValidationError("[request_cache] cannot be used in a scroll context", validationException);
            }
        }
        if (source != null) {
            if (source.slice() != null) {
                if (source.pointInTimeBuilder() == null && (scroll == false)) {
                    validationException = addValidationError(
                        "[slice] can only be used with [scroll] or [point-in-time] requests",
                        validationException
                    );
                }
            }
            if (source.from() > 0 && CollectionUtils.isEmpty(source.searchAfter()) == false) {
                validationException = addValidationError(
                    "[from] parameter must be set to 0 when [search_after] is used",
                    validationException
                );
            }
            if (source.storedFields() != null) {
                if (source.storedFields().fetchFields() == false) {
                    if (source.fetchSource() != null && source.fetchSource().fetchSource()) {
                        validationException = addValidationError(
                            "[stored_fields] cannot be disabled if [_source] is requested",
                            validationException
                        );
                    }
                    if (source.fetchFields() != null) {
                        validationException = addValidationError(
                            "[stored_fields] cannot be disabled when using the [fields] option",
                            validationException
                        );
                    }

                }
            }
            if (source.subSearches().size() >= 2 && source.rankBuilder() == null) {
                validationException = addValidationError("[sub_searches] requires [rank]", validationException);
            }
            if (source.aggregations() != null) {
                validationException = source.aggregations().validate(validationException);
            }
            validationException = validate(validationException, scroll);
            if (source.rescores() != null) {
                for (@SuppressWarnings("rawtypes")
                RescorerBuilder rescoreBuilder : source.rescores()) {
                    validationException = rescoreBuilder.validate(this, validationException);
                }
            }
        }
        if (pointInTimeBuilder() != null) {
            if (scroll) {
                validationException = addValidationError("using [point in time] is not allowed in a scroll context", validationException);
            }
            if (indices().length > 0) {
                validationException = addValidationError(
                    "[indices] cannot be used with point in time. Do not specify any index with point in time.",
                    validationException
                );
            }
            if (indicesOptions().equals(DEFAULT_INDICES_OPTIONS) == false) {
                validationException = addValidationError("[indicesOptions] cannot be used with point in time", validationException);
            }
            if (routing() != null) {
                validationException = addValidationError("[routing] cannot be used with point in time", validationException);
            }
            if (preference() != null) {
                validationException = addValidationError("[preference] cannot be used with point in time", validationException);
            }
        } else if (source != null && source.sorts() != null) {
            for (SortBuilder<?> sortBuilder : source.sorts()) {
                if (sortBuilder instanceof FieldSortBuilder
                    && ShardDocSortField.NAME.equals(((FieldSortBuilder) sortBuilder).getFieldName())) {
                    validationException = addValidationError(
                        "[" + FieldSortBuilder.SHARD_DOC_FIELD_NAME + "] sort field cannot be used without [point in time]",
                        validationException
                    );
                }
            }
        }
        if (minCompatibleShardNode() != null) {
            if (isCcsMinimizeRoundtrips()) {
                validationException = addValidationError(
                    "[ccs_minimize_roundtrips] cannot be [true] when setting a minimum compatible " + "shard version",
                    validationException
                );
            }
        }
        if (pointInTimeBuilder() != null && waitForCheckpoints.isEmpty() == false) {
            validationException = addValidationError("using [point in time] is not allowed with wait_for_checkpoints", validationException);

        }
        return validationException;
    }

    private ActionRequestValidationException validate(ActionRequestValidationException validationException, boolean scroll) {
        if (source.rankBuilder() != null) {
            int size = source.size() == -1 ? SearchService.DEFAULT_SIZE : source.size();
            if (size == 0) {
                validationException = addValidationError("[rank] requires [size] greater than [0]", validationException);
            }
            if (size > source.rankBuilder().rankWindowSize()) {
                validationException = addValidationError(
                    "[rank] requires [rank_window_size: "
                        + source.rankBuilder().rankWindowSize()
                        + "]"
                        + " be greater than or equal to [size: "
                        + size
                        + "]",
                    validationException
                );
            }
            int queryCount = source.subSearches().size() + source.knnSearch().size();
            if (source.rankBuilder().isCompoundBuilder() && queryCount < 2) {
                validationException = addValidationError(
                    "[rank] requires a minimum of [2] result sets using a combination of sub searches and/or knn searches",
                    validationException
                );
            }
            if (scroll) {
                validationException = addValidationError("[rank] cannot be used in a scroll context", validationException);
            }
            if (source.rescores() != null && source.rescores().isEmpty() == false) {
                validationException = addValidationError("[rank] cannot be used with [rescore]", validationException);
            }
            if (source.sorts() != null && source.sorts().isEmpty() == false) {
                validationException = addValidationError("[rank] cannot be used with [sort]", validationException);
            }
            if (source.collapse() != null) {
                validationException = addValidationError("[rank] cannot be used with [collapse]", validationException);
            }
            if (source.suggest() != null && source.suggest().getSuggestions().isEmpty() == false) {
                validationException = addValidationError("[rank] cannot be used with [suggest]", validationException);
            }
            if (source.highlighter() != null) {
                validationException = addValidationError("[rank] cannot be used with [highlighter]", validationException);
            }
            if (source.pointInTimeBuilder() != null) {
                validationException = addValidationError("[rank] cannot be used with [point in time]", validationException);
            }
        }
        return validationException;
    }

